// Sound set. Files live in public/audio (generated by `npm run sounds`; replace with real
// recordings of the same name later). Volumes are relative, 0..1.

export interface SoundDef {
  readonly file: string;
  readonly volume: number;
  readonly loop?: boolean;
}

export const SOUNDS = {
  spin: { file: 'spin.wav', volume: 0.35, loop: true },
  stop: { file: 'stop.wav', volume: 0.6 },
  anticipation: { file: 'anticipation.wav', volume: 0.6 },
  coin: { file: 'coin.wav', volume: 0.5 },
  winSmall: { file: 'win-small.wav', volume: 0.6 },
  winMedium: { file: 'win-medium.wav', volume: 0.7 },
  winBig: { file: 'win-big.wav', volume: 0.8 },
  net: { file: 'net.wav', volume: 0.7 },
  shot: { file: 'shot.wav', volume: 0.8 },
  meter: { file: 'meter.wav', volume: 0.6 },
  retrigger: { file: 'retrigger.wav', volume: 0.8 },
  fsStart: { file: 'fs-start.wav', volume: 0.8 },
  fsEnd: { file: 'fs-end.wav', volume: 0.8 },
  musicBase: { file: 'music-base.wav', volume: 0.35, loop: true },
  musicFree: { file: 'music-free.wav', volume: 0.45, loop: true },
} as const satisfies Record<string, SoundDef>;

export type SoundId = keyof typeof SOUNDS;
export type MusicId = 'musicBase' | 'musicFree';

export const AUDIO = {
  /** Folder (relative to the page) holding the sound files. */
  basePath: 'audio/',
  defaultVolume: 0.7,
  /** Seconds to cross-fade between music tracks. */
  musicFade: 1.0,
  /** Line wins below this many times the bet use the small jingle, below `medium` the medium one. */
  winJingle: { medium: 5 },
} as const;
